<script lang="ts">
	/**
	 * Supplied brand animation for the AI disclosure. Inlined so its fills can
	 * follow the theme tokens, and loaded lazily by AiFirstUseNotice because it
	 * is shown exactly once per browser — there is no reason to carry it in the
	 * route chunk for everyone who has already seen it.
	 */
	let { size = 132 }: { size?: number } = $props();

	let svgEl = $state<SVGSVGElement | undefined>(undefined);

	// SMIL ignores prefers-reduced-motion, so honour it directly.
	$effect(() => {
		if (svgEl && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
			svgEl.pauseAnimations();
		}
	});
</script>

